solution:
def is_not_prime(n: int) -> bool:
    if n < 2:
        return True
    if n == 2:
        return False
    if n % 2 == 0:
        return True
    limit = int(n**0.5) + 1
    for i in range(3, limit, 2):
        if n % i == 0:
            return True
    return False

import heapq

def heap_queue_largest(numbers, n):
    if n < 1 or not numbers:
        return []
    n = min(n, len(numbers))
    return heapq.nlargest(n, numbers)

def differ_At_One_Bit_Pos(a, b):
    a, b = abs(a), abs(b)
    if a == b:
        return False
    xor = a ^ b
    return xor != 0 and (xor & (xor - 1)) == 0

