def find_char_long(s: str) -> set:
    words = s.split()
    return {word for word in words if len(word) >= 4}

def find_Rotations(s: str) -> int:
    n = len(s)
    for i in range(1, n + 1):
        if n % i == 0:
            if s == s[i:] + s[:i]:
                return i
    return n

def remove_Occ(s, c):
    if not s:
        return ""
    first = s.find(c)
    last = s.rfind(c)
    if first == -1:
        return s
    if first == last:
        return s[:first] + s[first+1:]
    return s[:first] + s[first+1:last] + s[last+1:]

def find_Volume(base, height, length):
    if not all(isinstance(x, int) for x in (base, height, length)):
        return 0
    if base <= 0 or height <= 0 or length <= 0:
        return 0
    return (base * height * length) // 2

import re

def text_lowercase_underscore(s):
