        return False
    return bool(re.search(r'^[a-z]+(_[a-z]+)+$', s))

def remove_dirty_chars(dirty_chars: str, clean_chars: str) -> str:
    clean_set = set(clean_chars)
    return ''.join(ch for ch in dirty_chars if ch not in clean_set)

def find_Max_Num(digits):
    if not digits:
        return 0
    if not all(isinstance(d, int) for d in digits):
        raise ValueError("All elements must be integers")
    digits_sorted = sorted(digits, reverse=True)
    # If all digits are zero, return 0
    if all(d == 0 for d in digits_sorted):
        return 0
    return int(''.join(map(str, digits_sorted)))

def opposite_Signs(a: int, b: int) -> bool:
    if a == 0 or b == 0:
        return False
    return (a > 0 and b < 0) or (a < 0 and b > 0)

