    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    return n * (3 * n - 2)

def count_Substrings(s: str) -> int:
    n = len(s)
    count = 0
    for i in range(n):
        total = 0
        for j in range(i, n):
            total += int(s[j])
            if total == (j - i + 1):
                count += 1
    return count

