def get_equal(tuples):
    if not isinstance(tuples, list):
        raise TypeError("Input must be a list of tuples")
    if not tuples:
        return True
    first_length = len(tuples[0])
    for t in tuples:
        if not isinstance(t, tuple):
            raise TypeError("All elements must be tuples")
        if len(t) != first_length:
            return False
    return True

