def is_samepatterns(patterns1, patterns2):
    if len(patterns1) != len(patterns2):
        return False
    if not patterns1 and not patterns2:
        return True

    def pattern_to_indices(patterns):
        mapping = {}
        for i, p in enumerate(patterns):
            if p not in mapping:
                mapping[p] = []
            mapping[p].append(i)
        return sorted(mapping.values())

    return pattern_to_indices(patterns1) == pattern_to_indices(patterns2)

