def index_minimum(lst):
    if not isinstance(lst, list):
        raise TypeError("Input must be a list")
    if not lst:
        return None
    min_value = None
    min_first = None
    for item in lst:
        if not isinstance(item, tuple) or len(item) < 2:
            raise TypeError("All elements must be tuples with at least two elements")
        if min_value is None or item[1] < min_value:
            min_value = item[1]
            min_first = item[0]
    return min_first

