def next_smallest_palindrome(n):
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 1

    def is_palindrome(x):
        s = str(x)
        return s == s[::-1]

    candidate = n + 1
    while True:
        if is_palindrome(candidate):
            return candidate
        candidate += 1

