solution:
def kth_element(arr, k):
    if not isinstance(k, int):
        raise TypeError("k must be an integer")
    if k < 1 or k > len(arr):
        raise ValueError("k is out of bounds")
    return arr[k - 1]

def snake_to_camel(s: str) -> str:
    if not s:
        return ""
    parts = s.split('_')
    return ''.join(word.capitalize() for word in parts)

def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 1:
        return 1 if m == 0 else 0
    return (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m)

def odd_Equivalent(binary_str, rotations):
    if not binary_str:
        return 0

    n = len(binary_str)
    rotations = rotations % n if n else 0

    def rotate(s, k):
        return s[k:] + s[:k]

    # If rotations == 0 after modulo, consider all rotations (0 to n-1)
    total_rotations = rotations if rotations != 0 else n

    unique_rotated_strings = set()
    count_odd = 0

    for i in range(total_rotations):
        rotated_str = rotate(binary_str, i)
        if rotated_str not in unique_rotated_strings:
            unique_rotated_strings.add(rotated_str)
            if int(rotated_str, 2) % 2 == 1:
                count_odd += 1

    return count_odd

