solution:
def tuple_to_int(t):
    if t is None or len(t) == 0:
        raise TypeError("Input tuple cannot be None or empty")
    if not all(isinstance(x, int) for x in t):
        raise TypeError("All elements must be integers")
    if not all(x > 0 for x in t):
        raise ValueError("All elements must be positive integers")
    return int(''.join(str(x) for x in t))

assert tuple_to_int((1,2,3)) == 123

def string_to_list(input_string):
    """
    Converts a string to a list of strings split on the space character.
    """
    # Handle empty string or whitespace-only input
    if not input_string or not input_string.strip():
        return []

    # Split the string by spaces and return the resulting list
    return input_string.split(' ')

def search(arr):
    n = len(arr)
    if n == 1:
        return arr[0]
    for i in range(0, n, 2):
        if i == n - 1 or arr[i] != arr[i + 1]:
            return arr[i]

def max_product_tuple(lst):
    if not lst:
        return 0
    max_product = 0
    for a, b in lst:
        product = abs(a * b)
        if product > max_product:
            max_product = product
    return max_product

def amicable_numbers_sum(n):
    def sum_proper_divisors(x):
        total = 1
        p = 2
        while p * p <= x:
            if x % p == 0:
                total += p
                if p != x // p:
                    total += x // p
            p += 1
        if x == 1:
            return 0
        return total

    def is_amicable(num):
        if num == 1:
            return False
        s = sum_proper_divisors(num)
        if s == num or s == 0:
            return False
        return sum_proper_divisors(s) == num

    total_sum = 0
    for i in range(1, n + 1):
        if is_amicable(i):
            total_sum += i
    return total_sum

