    if not isinstance(z, complex):
        raise TypeError("Input must be a complex number")
    if z == 0:
        return None
    return cmath.phase(z)

assert math.isclose(angle_complex(1j), 1.5707963267948966, rel_tol=0.001)

def find_length(s: str) -> int:
    max_diff = float('-inf')
    current_diff = 0
    for char in s:
        if char == '0':
            current_diff += 1
        else:
            current_diff -= 1
        if current_diff > max_diff:
            max_diff = current_diff
        if current_diff < 0:
            current_diff = 0
    return max_diff if max_diff != float('-inf') else 0

def sum(a, b):
    a, b = abs(a), abs(b)
    if a == 0 or b == 0:
        return 0
    total = 0
    limit = min(a, b)
    for i in range(1, limit + 1):
        if a % i == 0 and b % i == 0:
            total += i
    return total

def long_words(n, words):
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if n < 0:
        return words
    return [word for word in words if len(word) > n]

def magic_square_test(matrix):
    if not matrix or not all(isinstance(row, list) for row in matrix):
        return False
    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return False
    # Check all elements are integers
    for row in matrix:
        for elem in row:
            if not isinstance(elem, int):
                return False
    # Calculate magic constant
    S = n * (n**2 + 1) // 2
    # Check rows
    for row in matrix:
        if sum(row) != S:
            return False
    # Check columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != S:
            return False
    # Check main diagonal
    if sum(matrix[i][i] for i in range(n)) != S:
        return False
    # Check anti-diagonal
    if sum(matrix[i][n - 1 - i] for i in range(n)) != S:
        return False
    return True
